/* src/menu/marena_match.cpp - the MATCH opponent list of the Arena ranking flow (OLMENU, the MArenaMatch_NewSystem
 * mobj). Seven MUnitRankerName2 rows (six visible, one spare used while scrolling) show the AutoGenerate opponents
 * (MArenaBridge_GetAutoGenerateData), a MUnitArenaMatch cursor marks the highlighted row and a MUnitArenaFrame shows
 * the highlighted opponent; the parent's MRankingMng is borrowed. PlayPhaseMain moves the cursor / scrolls with the
 * pad repeat pulses, toggles the frame mode, cancels or opens the "fight this one?" dialog; Play dispatches by phase
 * (1 main, 2 dialog, 3 picked -> next stage, 4 fade out + delete, 5 back from a child).
 * The whole file is native (g1). Original quirks kept: GetAutoGenerateDataNum / GetAutoGenerateData are called
 * afresh at every use (interpreted callees, call counts kept); the left rotate of the row ring copies one slot past
 * the array (a[6] = pMobjUnitArenaMatch, then overwritten with the old a[0]); the Class arm of the rank / name rule
 * skips DF_MSTR_GetName and uses the record's own name; the up / down repeat arms do not return, so a repeat pulse
 * and a face button in the same frame both act; ChangeCursor gets the old cursor in a2, which the callee ignores. */
#include <string.h>
#include "acnb/sdk.h"

#define MAM_WORK(p) ((struct struct_2420ef28 *)&(p)->dt)

/* "f_draw = 0, f_erase = 1" (two read-modify-writes of byte 0 in the original) */
static inline void mam_erase(struct stMobj *o)
{
    o->f_draw = 0;
    o->f_erase = 1;
}

static inline struct stAutoGenerateData *mam_data(int idx)
{
    return &MArenaBridge_GetAutoGenerateData()[(signed char)idx];
}

/* The rank / name rule: Class != 0 -> rank (Class >> 1) + 100 and the record's own name (nameAC or namePilot),
 * else rank = Rank and the string table name (base 0x7a11f AC names, 0x7a183 pilot names) */
static inline char *mam_rank_name(struct stAutoGenerateData *e, int *rank, int pilot)
{
    signed char cls = e->flagSearch.Class.Data;
    if (cls != 0) {
        *rank = (cls >> 1) + 100;
        return pilot ? e->namePilot : e->nameAC;
    }
    *rank = e->flagSearch.Rank;
    return (char *)DF_MSTR_GetName(MenuMng.language, 0, (unsigned int)*rank + (pilot ? 0x7a183u : 0x7a11fu));
}

/* frame + ranking for the highlighted opponent (data re-fetched for the id, as the original) */
static inline void mam_show_current(struct struct_2420ef28 *g)
{
    int rank;
    struct stAutoGenerateData *e = mam_data(g->data_index);
    char *name = mam_rank_name(e, &rank, 0);
    MUnitArenaFrame_SetData(g->pMobjUnitArenaFrame, name, rank);
    MRankingMng_SetNextReadID(g->pMobjRankingMng, mam_data(g->data_index)->id);
}

/* the spare row (a[6]) gets the scrolled-in opponent, placed at row pos, and every row fades with phase */
static inline void mam_scroll_start(struct struct_2420ef28 *g, char pos, char phase)
{
    int rank;
    struct stAutoGenerateData *e = mam_data(g->data_index);
    char *name = mam_rank_name(e, &rank, 1);
    MUnitRankerName2_SetStrings(g->apMobjUnitRankerName[6], rank, name, e->flagSearch.UserPointPlus,
                                e->flagSearch.UserPointMinus);
    MUnitRankerName2_SetPos(g->apMobjUnitRankerName[6], pos);
    for (int i = 0; i < 7; i++) MUnitRankerName2_FadeInStart(g->apMobjUnitRankerName[i], phase);
}

static inline signed char mam_num(void) { return (signed char)MArenaBridge_GetAutoGenerateDataNum(); }

static void __MArenaMatch_PlayPhaseMain(struct stMobj *pMobj)
{
    PS2_FRAME(0x80);
    struct struct_2420ef28 *g = MAM_WORK(pMobj);
    if (pMobj->stat == 1) {
        unsigned char c = pMobj->count;
        pMobj->count = c + 1;
        if (c < 6) return;
        pMobj->stat = 0;
    }
    if (MenuKeyGuide_IsShown()) return;
    if (MPad[MPadUser].start == 1) {
        MenuKeyGuide_Show(0x45);
        return;
    }
    if (MUnitRankerName2_IsMove(g->apMobjUnitRankerName[6])) return;

    if (g->stateMove != 0) {
        struct stMobj **a = g->apMobjUnitRankerName;
        if (g->stateMove == 1) {
            /* left: the original's loop also copies pMobjUnitArenaMatch (a[7]) into a[6] before the final store */
            struct stMobj *t = a[0];
            for (int i = 0; i < 6; i++) a[i] = a[i + 1];
            a[6] = t;
        } else {
            struct stMobj *t = a[5];
            for (int i = 5; i >= 1; i--) a[i] = a[i - 1];
            a[0] = a[6];
            a[6] = t;
        }
        for (int i = 0; i < 7; i++) MUnitRankerName2_SetID(a[i], (char)i);
        g->stateMove = 0;
        return;
    }

    if (MPad[MPadUser].repeat.dw == 1) {
        signed char old = g->cursor_index;
        Voice_Call(0x3e9, 0x7f);
        g->data_index = g->data_index + 1;
        if (!(g->data_index < mam_num())) g->data_index = 0;
        mam_show_current(g);
        g->cursor_index = g->cursor_index + 1;
        int lim = 5;
        if (mam_num() - 1 < 5) lim = mam_num() - 1;
        if (lim < g->cursor_index) {
            if (mam_num() - 1 < 6)
                g->cursor_index = 0;
            else
                g->cursor_index = 5;
            if (mam_num() - 1 >= 6) {
                mam_scroll_start(g, 6, 0x13);
                g->stateMove = 1;
            }
        }
        (void)old;   /* a2 of ChangeCursor (unused by the callee) */
        MUnitArenaMatch_ChangeCursor(g->pMobjUnitArenaMatch, g->cursor_index);
    }

    if (MPad[MPadUser].repeat.up == 1) {
        signed char old = g->cursor_index;
        Voice_Call(0x3e9, 0x7f);
        g->data_index = g->data_index - 1;
        if (g->data_index < 0) g->data_index = mam_num() - 1;
        mam_show_current(g);
        g->cursor_index = g->cursor_index - 1;
        if (g->cursor_index < 0) {
            if (mam_num() - 1 < 6)
                g->cursor_index = mam_num() - 1;
            else
                g->cursor_index = 0;
            if (mam_num() - 1 >= 6) {
                mam_scroll_start(g, -1, 0x15);
                g->stateMove = 2;
            }
        }
        (void)old;
        MUnitArenaMatch_ChangeCursor(g->pMobjUnitArenaMatch, g->cursor_index);
    }

    if (MPad[MPadUser].Rup == 1) {
        MUnitArenaFrame_ChangeMode(g->pMobjUnitArenaFrame, -1);
        MRankingMng_ChangeEmblemMode(g->pMobjRankingMng, -1);
    } else if (MPad[MPadUser].Rrt == 1) {
        Voice_Call(0x3eb, 0x7f);
        g->phase = 4;
        pMobj->count = 0;
        for (int i = 0; i < 7; i++) MUnitRankerName2_FadeOutStart(g->apMobjUnitRankerName[i], 0xd);
        MUnitArenaMatch_FadeOutStart(g->pMobjUnitArenaMatch, 0xd);
        MUnitArenaFrame_FadeOutStart(g->pMobjUnitArenaFrame, 0xd);
        MRankingMng_SetShow(g->pMobjRankingMng, 0);
    } else if (MPad[MPadUser].Rdw == 1) {
        Voice_Call(0x3ea, 0x7f);
        DF_MDIALOG_Open(2, DF_MSTR_GetName(MenuMng.language, 1, 0xdbf7e), 0, 0, 0, 0, 0, 0);
        g->phase = 2;
    }
}

static void __MArenaMatch_DeleteItem(struct stMobj *pMobj)
{
    PS2_FRAME(0x40);
    struct struct_2420ef28 *g = MAM_WORK(pMobj);
    for (int i = 0; i < 7; i++) {
        MUnitRankerName2_Cleanup(g->apMobjUnitRankerName[i]);
        if (g->apMobjUnitRankerName[i]) {
            mam_erase(g->apMobjUnitRankerName[i]);
            g->apMobjUnitRankerName[i] = 0;
        }
    }
    MUnitArenaMatch_Cleanup(g->pMobjUnitArenaMatch);
    if (g->pMobjUnitArenaMatch) {
        mam_erase(g->pMobjUnitArenaMatch);
        g->pMobjUnitArenaMatch = 0;
    }
    MUnitArenaFrame_Cleanup(g->pMobjUnitArenaFrame);
    if (g->pMobjUnitArenaFrame) {
        mam_erase(g->pMobjUnitArenaFrame);
        g->pMobjUnitArenaFrame = 0;
    }
    if (!((unsigned int)(MenuMng.stat - 2) < 5)) DF_MBACK_PopSceneLabel();
}

static void __MArenaMatch_FadeInItem(struct stMobj *pMobj, char phase)
{
    PS2_FRAME(0x60);
    struct struct_2420ef28 *g = MAM_WORK(pMobj);
    for (int i = 0; i < 7; i++) MUnitRankerName2_FadeInStart(g->apMobjUnitRankerName[i], phase);
    MUnitArenaMatch_FadeInStart(g->pMobjUnitArenaMatch, phase, (char)(mam_num() - 1 >= 6));
    MUnitArenaFrame_FadeInStart(g->pMobjUnitArenaFrame, phase);
    if (!((unsigned int)(MenuMng.stat - 2) < 5))
        DF_M1HELP_ChangeString(DF_MSTR_GetInfo(MenuMng.language, 0, 0xdbc15));
    DF_MVIEW_MotionStart(MViewp, 0x54);
    int rank;
    struct stAutoGenerateData *e = mam_data(g->data_index);
    char *name = mam_rank_name(e, &rank, 0);
    MUnitArenaFrame_SetData(g->pMobjUnitArenaFrame, name, rank);
    MRankingMng_SetShow(g->pMobjRankingMng, 1);
}

static void __MArenaMatch_CreateItem(struct stMobj *pMobj)
{
    PS2_FRAME(0x80);
    struct struct_2420ef28 *g = MAM_WORK(pMobj);
    signed char count = 7;
    if (mam_num() < 8) count = mam_num();
    for (int i = 0; i < 7; i++) g->apMobjUnitRankerName[i] = MUnitRankerName2_NewSystem(pMobj, (char)i);
    for (int j = 0; j < count; j++) {
        int rank;
        struct stAutoGenerateData *e = mam_data(j);
        char *name = mam_rank_name(e, &rank, 1);
        MUnitRankerName2_SetStrings(g->apMobjUnitRankerName[(signed char)j], rank, name, e->flagSearch.UserPointPlus,
                                    e->flagSearch.UserPointMinus);
    }
    g->pMobjUnitArenaMatch = MUnitArenaMatch_NewSystem(pMobj);
    g->pMobjUnitArenaFrame = MUnitArenaFrame_NewSystem(pMobj, 0);
    DF_MBACK_PushSceneLabel((enum_5124d09c)0xb);
}

static void __MArenaMatch_Pkt(void) {}

static void __MArenaMatch_Draw(void) {}

static void __MArenaMatch_Play(struct stMobj *pMobj)
{
    PS2_FRAME(0x50);
    struct struct_2420ef28 *g = MAM_WORK(pMobj);
    unsigned char c;
    switch (g->phase) {
    case 1:
        __MArenaMatch_PlayPhaseMain(pMobj);
        break;
    case 2:
        if ((DF_MDIALOG_Sync() & 4) != 4) break;
        if (DF_MDIALOG_Sync() & 0x10) {
            g->phase = 3;
            pMobj->count = 0;
            for (int i = 0; i < 7; i++) MUnitRankerName2_FadeOutStart(g->apMobjUnitRankerName[i], 9);
            MUnitArenaMatch_FadeOutStart(g->pMobjUnitArenaMatch, 9);
            MUnitArenaFrame_FadeOutStart(g->pMobjUnitArenaFrame, 9);
            MRankingMng_SetShow(g->pMobjRankingMng, 0);
        } else {
            g->phase = 1;
        }
        break;
    case 3:
        MArenaBridge_GetAutoGenerateData();   /* result unused (original) */
        MArenaStarter_CreateNextStageInfo(1, g->data_index);
        DF_MENU_SetFadeOut(6);
        DF_MBACK_SetFadeOutNX();   /* the original passes a0 = 0 */
        Bgm_FadeOutStart();
        DF_MBACK_PushSceneLabel((enum_5124d09c)0);
        DF_MBGUIDE_Hide();
        DF_M1HELP_FadeOut();
        g->phase = 4;
        pMobj->count = 0;
        for (int i = 0; i < 7; i++) MUnitRankerName2_FadeOutStart(g->apMobjUnitRankerName[i], 0xd);
        MUnitArenaMatch_FadeOutStart(g->pMobjUnitArenaMatch, 0xd);
        MUnitArenaFrame_FadeOutStart(g->pMobjUnitArenaFrame, 0xd);
        MRankingMng_SetShow(g->pMobjRankingMng, 0);
        break;
    case 4:
        c = pMobj->count;
        pMobj->count = c + 1;
        if (c < 6) break;
        for (int i = 0; i < 3; i++)
            if (MUnitRankerName2_IsMove(g->apMobjUnitRankerName[i])) return;
        __MArenaMatch_DeleteItem(pMobj);
        pMobj->stat = 5;
        pMobj->play_func = 0;
        pMobj->draw_func = 0;
        pMobj->pkt_func = 0;
        break;
    case 5:
        if (!g->pChild) break;
        if (g->pChild->stat != 5) break;
        if (!DF_MVIEW_MotionSync(MViewp)) break;
        if (g->pChild) {
            mam_erase(g->pChild);
            g->pChild = 0;
        }
        g->phase = 1;
        pMobj->stat = 1;
        pMobj->count = 0;
        __MArenaMatch_FadeInItem(pMobj, 5);
        break;
    default:
        break;
    }
}

/* Creates the MATCH list mobj (pParentMobj goes to DF_MOBJ_GetNewObject untouched in a0) */
struct stMobj *MArenaMatch_NewSystem(struct stMobj *pParentMobj, struct stMobj *pMobjRankingMng)
{
    PS2_FRAME(0x40);
    struct stMobj *m = DF_MOBJ_GetNewObject(pParentMobj);
    if (!m) return 0;
    struct struct_2420ef28 *g = MAM_WORK(m);
    memset(g, 0, 0x34);
    g->pMobjRankingMng = pMobjRankingMng;
    m->type = 0;
    m->stat = 1;
    m->count = 0;
    m->play_func = (void (*)(void))GFN(__MArenaMatch_Play);
    m->draw_func = (void (*)(void))GFN(__MArenaMatch_Draw);
    m->pkt_func = (void (*)(void))GFN(__MArenaMatch_Pkt);
    __MArenaMatch_CreateItem(m);
    g->phase = 1;
    m->stat = 1;
    m->count = 0;
    __MArenaMatch_FadeInItem(m, 1);
    return m;
}
